const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 10h10M7 14h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m7 10 5 5 5-5"/>',back:'<path d="m14 6-6 6 6 6M8 12h12"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',filters:'<path d="M4 7h9m4 0h3M4 17h3m4 0h9"/><circle cx="15" cy="7" r="2"/><circle cx="9" cy="17" r="2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',phone:'<path d="M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4c0 2-2 3-4 2A23 23 0 0 1 3 7c-1-2 0-4 2-4Z"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',send:'<path d="m22 2-7 20-4-9L2 9Zm0 0L11 13"/>',check:'<path d="m5 12 4 4L19 6"/>',wave:'<path d="M3 10v4m4-7v10m5-14v18m5-14v10m4-7v4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.heart}</svg>`;
const categories=[{name:'Politica e Sociale',desc:'Attualità, idee e nuovi punti di vista.',n:21,tags:['Attualità','Politica','Società'],color:'#fdf8f4'},{name:'Cinema',desc:'Storie che restano, anche dopo i titoli.',n:18,tags:['Film','Registi','Grandi storie'],color:'#fff7f5'},{name:'Musica',desc:'La tua prossima affinità, in cuffia.',n:32,tags:['Concerti','Playlist','Artisti'],color:'#f9f6ff'},{name:'Sport',desc:'Passioni da vivere, dentro e fuori campo.',n:16,tags:['Corsa','Calcio','All’aperto'],color:'#f2faf7'},{name:'Anime & Serie',desc:'Un altro episodio. Un’altra affinità.',n:24,tags:['Anime','Serie TV','Manga'],color:'#fff5fa'},{name:'Cultura',desc:'Libri, curiosità e idee da condividere.',n:12,tags:['Libri','Arte','Viaggi'],color:'#fcf9f0'},{name:'Teatro',desc:'Emozioni che meritano un bis.',n:9,tags:['Spettacoli','Musical','Palcoscenico'],color:'#fcf5fa'},{name:'Gaming',desc:'La passione è già un punto in comune.',n:27,tags:['Videogiochi','Co-op','Indie'],color:'#f4f7ff'}];
let state={view:'home',category:0,matched:false,muted:false,speaker:true,name:'Riccardo',age:28,gender:'Uomo',city:'Roma',preference:'Donne',min:24,max:32,interests:['Cinema','Musica','Politica e Sociale'],messages:[],onboard:0};let timers=[];let callSeconds=0;const app=document.getElementById('app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const later=(f,n)=>timers.push(setTimeout(f,n));
function nav(){const entries=[['home','home','Esplora'],['matches','heart','Connessioni'],['messages','chat','Chat'],['profile','user','Profilo']];let html=entries.map(([view,i,label])=>`<button onclick="go('${view}')" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('');document.getElementById('desktop-nav').innerHTML=html;document.getElementById('mobile-nav').innerHTML=html;document.querySelector('.avatar').textContent=state.name.charAt(0).toUpperCase()}
function go(view){timers.forEach(clearTimeout);timers=[];state.view=view;render();window.scrollTo({top:0,behavior:'instant'});nav()}
function art(i,cls='category-art'){return `<div class="${cls}" data-art="${i}" aria-hidden="true"></div>`}
function filters(){return `<div class="filters"><button class="filter-chip" onclick="openFilters()">${icon('user')}${esc(state.preference)}${icon('down')}</button><button class="filter-chip" onclick="openFilters()">${state.min}–${state.max} anni${icon('down')}</button><button class="filter-chip" onclick="openFilters()">${icon('pin')}${esc(state.city)}${icon('down')}</button><button class="filter-chip" onclick="openFilters()" aria-label="Tutti i filtri">${icon('filters')}<span class="filter-word">Filtri</span></button></div>`}
function render(){let html='';const c=categories[state.category];if(state.view==='home'){html=`<div class="home page-enter"><p class="eyebrow">Ciao, ${esc(state.name)}</p><h1>Che conversazione<br><span class="title-accent">cerchi oggi?</span></h1>${filters()}<div class="section-label"><h2>Scegli un argomento</h2><span>8 argomenti</span></div><div class="category-grid">${categories.map((c,i)=>`<button class="category" style="--room-color:${c.color};--card-order:${i}" onclick="selectCategory(${i})">${art(i)}<div class="category-content"><h3>${c.name}</h3><p>${c.desc}</p><div class="category-footer"><span>${c.n} compatibili ora</span>${icon('chevron')}</div></div></button>`).join('')}</div><p class="footnote">${icon('shield')}Conversazioni private, sempre tra due persone.</p></div>`}else{html=renderFlow(c)}app.innerHTML=html;document.body.dataset.view=state.view;loadArt();nav()}
function selectCategory(i){state.category=i;go('category')}
function renderCategory(c){return `<div class="flow page-enter"><button class="back" onclick="go('home')" aria-label="Torna alla home">${icon('back')}</button>${art(state.category,'large-art')}<p class="eyebrow">Il vostro punto in comune</p><h1>${c.name}</h1><p class="lead">${c.desc}</p><div class="pills">${c.tags.map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="compatible">${c.n} persone compatibili ora</p><div class="flow-actions"><button class="primary" onclick="startSearch()">${icon('wave')}Trova una persona</button><button class="text-button" onclick="openFilters()">${esc(state.preference)} · ${state.min}–${state.max} · ${esc(state.city)} ${icon('filters')}</button></div></div>`}
function loadArt(){const files=['agora','cinema','musica','sport','anime','cultura','default','gaming'];document.querySelectorAll('[data-art]').forEach(el=>{el.style.backgroundImage=`url('assets/rooms/${files[Number(el.dataset.art)]}.png')`})}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
function openFilters(){const d=document.getElementById('filter-dialog');d.innerHTML=`<form id="filters-form"><div class="dialog-head"><h2>Chi vuoi conoscere?</h2><button type="button" class="icon-button" onclick="document.getElementById('filter-dialog').close()" aria-label="Chiudi">${icon('close')}</button></div><p class="lead">Partiamo dalle tue preferenze.</p><label for="pref">Mi piacerebbe conoscere</label><select id="pref">${['Donne','Uomini','Tutte le persone'].map(v=>`<option ${v===state.preference?'selected':''}>${v}</option>`).join('')}</select><label>Fascia d’età</label><div class="range-pair"><input aria-label="Età minima" id="min" type="number" min="18" max="99" value="${state.min}" required><span>—</span><input aria-label="Età massima" id="max" type="number" min="18" max="99" value="${state.max}" required></div><label for="city">Città o regione</label><input id="city" value="${esc(state.city)}" required maxlength="40"><button class="primary" type="submit">Applica filtri</button></form>`;d.showModal();document.getElementById('filters-form').onsubmit=e=>{e.preventDefault();const min=+document.getElementById('min').value,max=+document.getElementById('max').value;if(min>max){toast('L’età minima deve essere inferiore alla massima.');return}Object.assign(state,{preference:document.getElementById('pref').value,min,max,city:document.getElementById('city').value.trim()||'Roma'});d.close();render();toast('Preferenze aggiornate')};}
window.addEventListener('hashchange',()=>{if(location.hash==='#home')go('home')});render();
// All identities, availability and replies in this prototype are demonstration data.
const baseRenderFlow=renderCategory;
function voiceStage(cls=''){const bars=Array.from({length:15},(_,i)=>`<i style="--bar-height:${[12,23,39,58,81,58,95,112,87,66,42,72,40,24,13][i]}px;--delay:${i*-.12}s"></i>`).join('');return `<div class="voice-stage ${cls}"><div class="voice-orb ${state.muted?'paused':''}">${bars}</div><div class="voice-link"></div><div class="voice-orb coral">${bars}</div></div>`}
function back(view='home'){return `<button class="back" onclick="go('${view}')" aria-label="Indietro">${icon('back')}</button>`}
function personName(){return state.preference==='Uomini'?'Luca':'Giulia'}
function personAge(){return Math.max(state.min,Math.min(27,state.max))}
function personAvatar(locked=true){return `<span class="avatar-wrap"><span class="person-avatar ${locked?'blurred':''} ${personName()==='Giulia'?'has-photo':''}">${personName()==='Giulia'?'<img src="assets/giulia.png" alt="">':(locked?'':personName()[0])}</span>${locked?icon('lock'):''}</span>`}
function renderFlow(c){const n=personName();if(state.view==='category')return baseRenderFlow(c);if(state.view==='search')return `<section class="flow page-enter">${back('category')}<p class="eyebrow">${c.name} · CONVERSAZIONE 1:1</p><h1>Stiamo cercando<br>qualcuno simile a te.</h1><p class="lead">Una passione in comune è un buon inizio.</p>${voiceStage('searching')}<p class="search-copy" aria-live="polite">Cerchiamo tra le persone compatibili…</p><div class="info-row">${icon('filters')}${esc(state.preference)} · ${state.min}–${state.max} anni · ${esc(state.city)}</div><div class="flow-actions"><button class="text-button" onclick="go('category')">Annulla ricerca</button></div></section>`;
if(state.view==='found')return `<section class="flow found page-enter">${back('category')}<p class="eyebrow">Una persona con cui parlare</p><h1>Abbiamo trovato<br>qualcuno simile a te.</h1><p class="lead">Prima la voce, poi il profilo.</p><div class="person-card"><div class="person-heading">${personAvatar()}<div class="person-identity"><h2>${n}, ${personAge()}</h2><p>${icon('pin')}${esc(state.city)}</p></div></div><p class="common-label">Avete in comune</p><div class="pills">${[c.name,...state.interests.filter(x=>x!==c.name)].slice(0,3).map(t=>`<span class="pill">${t}</span>`).join('')}</div><div class="voice-invitation">${icon('wave')}<p>Per ora, conoscetevi dalla voce.</p></div><p class="privacy-copy">Se vorrete risentirvi entrambi,<br>scoprirete anche i vostri profili.</p></div><div class="flow-actions"><button class="primary" onclick="startCall()">${icon('phone')}Connettiti con ${n}</button><button class="text-button" onclick="startSearch()">Cerca ancora</button></div><p class="footnote">Puoi terminare la chiamata in qualsiasi momento.</p></section>`;
if(state.view==='call')return `<section class="flow call page-enter"><p class="eyebrow">${c.name} · Solo voi due</p><h1>Tu e ${n}</h1><span class="call-time" id="call-time">00:00</span>${voiceStage()}<div class="voice-names"><span>Tu</span><span>${n}</span></div><div class="call-controls"><button class="control ${state.muted?'toggled':''}" onclick="toggleMute()" aria-pressed="${state.muted}" id="mute"><span>${icon('mic')}</span><label>${state.muted?'Riattiva':'Microfono'}</label></button><button class="control end" onclick="endCall()"><span>${icon('phone')}</span>Termina</button><button class="control ${!state.speaker?'toggled':''}" onclick="toggleSpeaker()" aria-pressed="${state.speaker}" id="speaker"><span>${icon('volume')}</span><label>Audio ${state.speaker?'attivo':'spento'}</label></button></div><p class="demo-note">Demo senza audio · microfono non attivo</p></section>`;
if(state.view==='feedback')return `<section class="flow page-enter"><p class="eyebrow">La vostra conversazione</p>${voiceStage('post-call-voices')}<h1>Ti piacerebbe<br>risentire ${n}?</h1><p class="lead">Se anche ${n} lo desidera, potrete continuare<br>a conoscervi e scoprire i vostri profili.</p><div class="conversation-context">${icon('clock')} ${formatTime(callSeconds)} insieme · ${c.name}</div><div class="flow-actions"><button class="primary" onclick="likePerson()">${icon('heart')}Sì, mi piacerebbe</button><button class="text-button" onclick="go('home');toast('Va bene così. La prossima conversazione ti aspetta.')">Non questa volta</button></div><p class="privacy-copy">La tua risposta resta privata, a meno che sia reciproca.</p></section>`;
if(state.view==='waiting')return `<section class="flow waiting page-enter"><p class="eyebrow">La tua risposta è privata</p>${voiceStage()}<h1>Vediamo se è reciproco.</h1><p class="lead">Aspettiamo la risposta di ${n}.</p><div class="flow-actions"><button class="secondary" onclick="go('home')">Torna a esplorare</button></div></section>`;
if(state.view==='matched')return `<section class="flow matched page-enter"><p class="eyebrow">Vi siete scelti</p><h1>Anche ${n}<br>vuole risentirti.</h1><div class="reveal-portrait">${n==='Giulia'?'<img src="assets/giulia.png" alt="Giulia, profilo dimostrativo">':`<div class="reveal-initial" role="img" aria-label="Foto non disponibile">${n.charAt(0)}</div>`}</div><div class="revealed-profile"><h2>${n}, ${personAge()}</h2><p class="lead">${esc(state.city)}</p><div class="pills">${[c.name,...state.interests.filter(t=>t!==c.name)].slice(0,3).map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="profile-intro">«Mi piacciono le persone curiose e le conversazioni che fanno perdere la cognizione del tempo.»</p></div><div class="flow-actions"><button class="primary" onclick="go('chat')">Continua con ${n}${icon('chevron')}</button></div><p class="privacy-copy">Il vostro profilo e la chat sono ora aperti.</p></section>`;
if(state.view==='matches'||state.view==='messages'){const isChat=state.view==='messages';return `<section class="page-enter"><p class="eyebrow">Il tuo spazio</p><h1>${isChat?'Le tue conversazioni':'Le tue connessioni'}</h1><p class="lead">${isChat?'Le belle conversazioni possono continuare.':'Le persone con cui la voglia di risentirsi è reciproca.'}</p>${state.matched?`<button class="list-card" onclick="go('${isChat?'chat':'person'}')">${personAvatar(false)}<div><h3>${n}, ${personAge()}</h3><p>${isChat?'Da una voce a un nuovo messaggio.':`${esc(state.city)} · Vi siete conosciuti in ${c.name}`}</p></div>${icon('chevron')}</button>`:`<div class="empty">${icon(isChat?'chat':'heart')}<h2>Si comincia da una voce.</h2><p>Dopo una chiamata, se entrambi volete risentirvi, ritroverai qui la vostra connessione.</p><button class="primary" onclick="go('home')">Trova una conversazione</button></div>`}</section>`}
if(state.view==='chat'){if(!state.matched){state.view='messages';return renderFlow(c)}return `<section class="chat page-enter"><div class="chat-heading">${back('messages')}${personAvatar(false)}<button class="small-link" style="text-align:left;padding:0" onclick="go('person')"><h2>${n}</h2><p>Visualizza profilo</p></button></div><div class="messages"><span class="chat-date">Oggi</span><div class="chat-unlock">Vi siete scelti, dopo esservi ascoltati.<br>La vostra conversazione può continuare qui.</div>${state.messages.map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.text)}<span class="bubble-time">${m.time}</span></div>`).join('')}</div><form class="composer" onsubmit="sendMessage(event)"><input id="message-input" aria-label="Il tuo messaggio" placeholder="Scrivi a ${n}…" maxlength="2000" autocomplete="off" required><button type="submit" aria-label="Invia messaggio">${icon('send')}</button></form><p class="privacy-copy" style="text-align:center">Chat dimostrativa · i messaggi restano in questa sessione</p></section>`}
if(state.view==='person'){if(!state.matched){state.view='matches';return renderFlow(c)}return `<section class="flow page-enter">${back('matches')}<p class="eyebrow">Piacere di conoscerti</p>${n==='Giulia'?'<img class="profile-portrait" src="assets/giulia.png" alt="Giulia, profilo dimostrativo">':`<div class="person-heading">${personAvatar(false)}</div>`}<h1>${n}, ${personAge()}</h1><p class="lead">${esc(state.city)}</p><div class="unlocked-profile"><h2>Piacere di conoscerti.</h2><p>Un film al cinema, un concerto improvvisato e le conversazioni che fanno perdere la cognizione del tempo. Mi piacciono le persone curiose.</p><p class="common-label">Le mie passioni</p><div class="pills">${[c.name,...state.interests.filter(t=>t!==c.name)].slice(0,4).map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="privacy-copy">${n==='Giulia'?'Profilo e fotografia dimostrativi':'Profilo dimostrativo · foto non caricata'}</p></div><div class="flow-actions"><button class="primary" onclick="go('chat')">${icon('chat')}Scrivi a ${n}</button></div></section>`}
if(state.view==='profile')return `<section class="profile page-enter"><p class="eyebrow">Il tuo spazio</p><h1>Il tuo profilo</h1><div class="profile-header"><div class="avatar" style="display:grid;place-items:center">${esc(state.name.charAt(0))}</div><div><h2>${esc(state.name)}, ${state.age}</h2><p class="lead">${esc(state.city)}</p></div></div><form onsubmit="saveProfile(event)"><label for="profile-name">Come ti chiami</label><input id="profile-name" value="${esc(state.name)}" maxlength="30" required><label for="profile-city">La tua città</label><input id="profile-city" value="${esc(state.city)}" maxlength="40" required><label>I tuoi interessi</label><div id="profile-interests">${categories.map(c=>`<button type="button" class="interest ${state.interests.includes(c.name)?'selected':''}" aria-pressed="${state.interests.includes(c.name)}" onclick="toggleProfileInterest(this,'${c.name}')">${c.name}</button>`).join('')}</div><button class="primary" type="submit">Salva modifiche</button></form><button class="text-button" onclick="startOnboarding()">Riprova l’onboarding</button><p class="footnote">${icon('lock')}Le informazioni restano in questa demo.</p></section>`;
if(state.view==='onboarding')return onboardingHtml();return baseRenderFlow(c)}
function startSearch(){go('search');later(()=>{if(state.view==='search')go('found')},3000)}
function formatTime(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function startCall(){state.muted=false;state.speaker=true;callSeconds=0;go('call');function tick(){if(state.view!=='call')return;callSeconds++;const t=document.getElementById('call-time');if(t)t.textContent=formatTime(callSeconds);later(tick,1000)}later(tick,1000)}
function toggleMute(){state.muted=!state.muted;const b=document.getElementById('mute');b.classList.toggle('toggled',state.muted);b.setAttribute('aria-pressed',state.muted);b.querySelector('label').textContent=state.muted?'Riattiva':'Microfono';document.querySelector('.voice-orb').classList.toggle('paused',state.muted)}
function toggleSpeaker(){state.speaker=!state.speaker;const b=document.getElementById('speaker');b.classList.toggle('toggled',!state.speaker);b.setAttribute('aria-pressed',state.speaker);b.querySelector('label').textContent=state.speaker?'Audio attivo':'Audio spento'}
function endCall(){state.muted=false;go('feedback')}
function likePerson(){go('waiting');later(()=>{state.matched=true;go('matched')},1600)}
function sendMessage(e){e.preventDefault();const inp=document.getElementById('message-input'),text=inp.value.trim();if(!text)return;state.messages.push({text,mine:true,time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});render();document.getElementById('message-input').focus();if(state.messages.filter(m=>m.mine).length===1)later(()=>{state.messages.push({text:'Mi ha fatto piacere parlare con te! Riprendiamo da dove eravamo rimasti?',mine:false,time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})});if(state.view==='chat')render()},1100)}
function toggleProfileInterest(b,name){if(state.interests.includes(name)){if(state.interests.length===1){toast('Scegli almeno un interesse.');return}state.interests=state.interests.filter(t=>t!==name)}else state.interests.push(name);b.classList.toggle('selected',state.interests.includes(name));b.setAttribute('aria-pressed',state.interests.includes(name))}
function saveProfile(e){e.preventDefault();const name=document.getElementById('profile-name').value.trim(),city=document.getElementById('profile-city').value.trim();if(!name||!city){toast('Inserisci il nome e la città.');return}state.name=name;state.city=city;render();toast('Profilo aggiornato')}
function startOnboarding(){state.onboard=0;go('onboarding')}
const onboardingQuestions=[['Partiamo da te.','Come ti chiami?','Il nome con cui ti presenterai alle altre persone.'],['PIACERE DI CONOSCERTI','Quanti anni hai?','Voemi è uno spazio per persone maggiorenni.'],['QUALCOSA SU DI TE','Come ti identifichi?','Scegli la definizione in cui ti riconosci.'],['VICINI, ANCHE NELLA VITA','Da dove ci ascolti?','La tua città ci aiuta a trovare persone vicine.'],['LE TUE PREFERENZE','Chi vorresti conoscere?','Puoi cambiare le tue preferenze in ogni momento.'],['UN PUNTO IN COMUNE','Cosa ti appassiona?','Scegli almeno un interesse. La conversazione inizia qui.']];
function onboardingHtml(){const q=onboardingQuestions[state.onboard];let field='';if([0,1,3].includes(state.onboard)){let val=state.onboard===0?state.name:state.onboard===1?state.age:state.city;field=`<label for="onboard-input">${state.onboard===0?'Il tuo nome':state.onboard===1?'La tua età':'La tua città'}</label><input id="onboard-input" ${state.onboard===1?'type="number" min="18" max="99"':'type="text" maxlength="40"'} value="${esc(val)}" required>`}if(state.onboard===2||state.onboard===4){const values=state.onboard===2?['Donna','Uomo','Non binario','Preferisco non specificarlo']:['Donne','Uomini','Tutte le persone'];const selected=state.onboard===2?state.gender:state.preference;field=values.map(v=>`<button type="button" class="choice ${v===selected?'selected':''}" aria-pressed="${v===selected}" onclick="chooseOnboard('${v}')">${v}${v===selected?' <span style="float:right">✓</span>':''}</button>`).join('')}if(state.onboard===5)field=categories.map(c=>`<button type="button" class="interest ${state.interests.includes(c.name)?'selected':''}" aria-pressed="${state.interests.includes(c.name)}" onclick="toggleProfileInterest(this,'${c.name}')">${c.name}</button>`).join('');return `<section class="onboard page-enter"><div style="display:flex;align-items:center;justify-content:space-between"><button class="back" onclick="onboardBack()" aria-label="Passaggio precedente">${icon('back')}</button><span class="eyebrow">${state.onboard+1} DI 6</span></div><div class="progress"><span style="width:${(state.onboard+1)/6*100}%"></span></div><p class="eyebrow">${q[0]}</p><h1>${q[1]}</h1><p class="lead">${q[2]}</p><form onsubmit="nextOnboard(event)" style="display:flex;flex-direction:column;flex:1"><div class="onboard-body">${field}</div><p class="onboard-error" id="onboard-error" role="alert"></p><div class="flow-actions"><button class="primary" type="submit">${state.onboard===5?'Trova la tua prossima conversazione':'Continua'}${icon('chevron')}</button></div></form><button class="small-link" onclick="go('home')">Torna all’esplorazione</button></section>`}
function chooseOnboard(v){if(state.onboard===2)state.gender=v;else state.preference=v;render()}
function onboardBack(){if(state.onboard===0)go('home');else{state.onboard--;render()}}
function nextOnboard(e){e.preventDefault();const i=document.getElementById('onboard-input');if(i){let v=i.value.trim();if(!v){document.getElementById('onboard-error').textContent='Compila questo campo per continuare.';return}if(state.onboard===1){const age=+v;if(!Number.isInteger(age)||age<18||age>99){document.getElementById('onboard-error').textContent='Inserisci un’età compresa tra 18 e 99 anni.';return}state.age=age}else if(state.onboard===0)state.name=v;else state.city=v}if(state.onboard===5){go('home');toast('Il tuo spazio è pronto. Buone conversazioni!')}else{state.onboard++;render()}}
const originalNav=nav;nav=function(){originalNav();document.body.classList.toggle('no-bottom-nav',['call','onboarding','found','search','feedback','waiting','matched'].includes(state.view));};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'voemi_explore_topic',description:'Navigate the Voemi demo to a conversation topic. Does not initiate a call.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:categories.map(c=>c.name)}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const index=categories.findIndex(c=>c.name===input?.topic);if(index<0)throw new Error('Unknown topic');selectCategory(index);return{view:state.view,topic:categories[index].name}}})).catch(()=>{});}catch{}}
render();
